<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { managementProvider as api, saveDownload, type DataFilter } from '@/services/management'
import { reportProvider } from '@/services/report'
import { useAuthStore } from '@/stores/auth'
import RegionPicker from '@/components/RegionPicker.vue'
import type { SurveyPeriod } from '@/types/report'
import type { Summary, EffectiveReportRow, EnterpriseInfoRow } from '@/types/management'
import { formLabels } from '@/utils/report'
import { formatBeijingTime } from '@/utils/filing'
const auth=useAuthStore(),periods=ref<SurveyPeriod[]>([]),periodCode=ref(''),regionCode=ref<string|null>(null),summary=ref<Summary|null>(null),reports=ref<EffectiveReportRow[]>([]),enterprises=ref<EnterpriseInfoRow[]>([]),total=ref(0),enterpriseTotal=ref(0),page=ref(1),enterprisePage=ref(1),busy=ref(false),error=ref(''),applied=ref<DataFilter|null>(null),traceId=ref('')
const enterpriseColumns:Partial<Record<keyof EnterpriseInfoRow,string>>={periodCode:'调查期',reportId:'报表ID',submissionVersion:'提交版本',orgId:'企业ID',organizationCode:'组织机构代码',enterpriseName:'企业名称',regionName:'地区',natureName:'企业性质',industryName:'所属行业',mainBusiness:'主要经营业务',contactName:'联系人',addressName:'联系地址',postalCode:'邮政编码',contactPhone:'联系电话',fax:'传真',email:'邮箱',filingSource:'备案来源',filingId:'备案ID',filingVersion:'备案版本'}
const sourceLabels={SNAPSHOT_VERSION:'提交时备案版本',CURRENT_FALLBACK:'当前备案回退（非历史冻结值）',UNAVAILABLE:'备案不可用'}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){if(!periodCode.value){error.value='请选择调查期';return}await run(async()=>{applied.value=null;summary.value=null;reports.value=[];enterprises.value=[];total.value=0;enterpriseTotal.value=0;const q={periodCode:periodCode.value,...(regionCode.value?{regionCode:regionCode.value}:{})};const [s,r,e]=await Promise.all([api.summary(q,auth.token!),api.reports({...q,page:0,size:20},auth.token!),api.enterprises({...q,page:0,size:20},auth.token!)]);summary.value=s.data;reports.value=r.data.items;total.value=r.data.total;enterprises.value=e.data.items;enterpriseTotal.value=e.data.total;page.value=1;enterprisePage.value=1;applied.value=q})}
async function changePage(enterprise=false){if(!applied.value)return;await run(async()=>{if(enterprise){const r=await api.enterprises({...applied.value!,page:enterprisePage.value-1,size:20},auth.token!);enterprises.value=r.data.items}else{const r=await api.reports({...applied.value!,page:page.value-1,size:20},auth.token!);reports.value=r.data.items}})}
async function exportFile(kind:'reports'|'enterprise-info'){if(applied.value)await run(async()=>saveDownload(await api.export(kind,applied.value!,auth.token!)))}
onMounted(()=>run(async()=>{periods.value=(await reportProvider.periods(auth.token!)).data.items}))
</script>
<template><section><h1>按调查期汇总与有效数据</h1><p>只统计本省已省审通过、未作废报表的最新提交版本，人数和原因使用有效修订值。净变化＝调查期人数－建档期人数。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-card v-loading="busy" shadow="never"><el-form inline><el-form-item label="调查期"><el-select v-model="periodCode" style="width:260px"><el-option v-for="p in periods" :key="p.code" :label="p.label" :value="p.code"/></el-select></el-form-item><el-form-item label="地区子树"><RegionPicker v-model="regionCode" any-level/></el-form-item><el-button type="primary" :disabled="busy" @click="load">查询 / 刷新</el-button></el-form><template v-if="summary"><h2>{{summary.periodLabel}}</h2><p>当前结果：{{applied?.periodCode}} · 地区 {{applied?.regionCode||'全省'}}；更改筛选后请重新查询。</p><dl class="summary-metrics"><div><dt>企业数</dt><dd>{{summary.enterpriseCount}}</dd></div><div><dt>建档期人数合计</dt><dd>{{summary.baselineEmploymentTotal}}</dd></div><div><dt>调查期人数合计</dt><dd>{{summary.periodEmploymentTotal}}</dd></div><div><dt>净变化</dt><dd>{{summary.netChange}}</dd></div></dl><el-table :data="summary.cities" empty-text="本期无符合条件的企业"><el-table-column prop="cityName" label="城市"/><el-table-column prop="enterpriseCount" label="企业数"/><el-table-column prop="baselineEmploymentTotal" label="建档期人数合计"/><el-table-column prop="periodEmploymentTotal" label="调查期人数合计"/><el-table-column prop="netChange" label="净变化"/></el-table><h2>有效企业报表</h2><el-button :disabled="busy" @click="exportFile('reports')">导出全部匹配报表 Excel</el-button><el-table :data="reports" empty-text="暂无符合条件的报表"><el-table-column prop="reportId" label="报表ID"/><el-table-column prop="periodCode" label="调查期" min-width="140"/><el-table-column prop="submissionVersion" label="提交版本"/><el-table-column prop="orgId" label="企业ID"/><el-table-column prop="enterpriseName" label="企业名称" min-width="160"/><el-table-column prop="organizationCode" label="组织机构代码" min-width="140"/><el-table-column prop="cityName" label="城市"/><el-table-column prop="regionName" label="地区"/><el-table-column v-for="(label,k) in formLabels" :key="k" :label="label" min-width="150"><template #default="s">{{s.row.effectiveForm[k]??'—'}}</template></el-table-column><el-table-column label="净变化"><template #default="s">{{s.row.effectiveForm.periodEmploymentCount-s.row.effectiveForm.baselineEmploymentCount}}</template></el-table-column><el-table-column prop="correctionCount" label="修订次数"/><el-table-column label="最近修订时间" min-width="180"><template #default="s">{{formatBeijingTime(s.row.lastCorrectedAt)}}</template></el-table-column><el-table-column label="操作" fixed="right" width="120"><template #default="s"><router-link :to="'/province/data/reports/'+s.row.reportId">修订 / 追溯</router-link></template></el-table-column></el-table><el-pagination v-model:current-page="page" :disabled="busy" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="changePage()"/><h2>报送期企业信息</h2><p>备案来源标为“当前备案回退”时，资料不代表提交时冻结版本。</p><el-button :disabled="busy" @click="exportFile('enterprise-info')">导出全部匹配企业信息 Excel</el-button><el-table :data="enterprises" empty-text="暂无符合条件的企业信息"><el-table-column v-for="(label,k) in enterpriseColumns" :key="k" :label="label" min-width="150"><template #default="s">{{k==='filingSource'?sourceLabels[s.row.filingSource as keyof typeof sourceLabels]:s.row[k]??'—'}}</template></el-table-column></el-table><el-pagination v-model:current-page="enterprisePage" :disabled="busy" :total="enterpriseTotal" :page-size="20" layout="total,prev,pager,next" @current-change="changePage(true)"/></template><el-empty v-else description="请选择调查期并查询"/></el-card><h2>按报表 ID 追溯</h2><p>已作废报表仍可凭原报表 ID 查看原值、修订和作废记录。</p><el-input v-model="traceId" placeholder="报表 ID" style="width:220px"/><router-link v-if="/^[1-9][0-9]*$/.test(traceId)" :to="'/province/data/reports/'+traceId">打开追溯详情</router-link></section></template>

<style scoped>.summary-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px}.summary-metrics div{border:1px solid #e5e8ee;padding:16px}.summary-metrics dt{color:#66788a}.summary-metrics dd{margin:8px 0 0;font-size:24px;font-weight:600}</style>
